#include "ui.h"
#include <stdio.h>

static lv_obj_t *s_focus_box, *s_target, *s_time, *s_delay, *s_status;
static int focus, mode, temp = 370, mins = 15, delay_s = 60;

static lv_obj_t *txt(lv_obj_t *p, const char *v, int x, int y, int w, int h, const lv_font_t *f)
{ lv_obj_t *o=lv_label_create(p); lv_label_set_text(o,v); lv_obj_set_pos(o,x,y); lv_obj_set_size(o,w,h); lv_obj_set_style_text_font(o,f,0); lv_obj_set_style_text_color(o,lv_color_hex(0x17324D),0); return o; }
static void redraw(void)
{ char b[32]; lv_label_set_text_fmt(s_target,"Target: %d.%d C",temp/10,temp%10); lv_label_set_text_fmt(s_time,"Incubation: %d min",mins); lv_label_set_text_fmt(s_delay,"Delay to 4C: %d s",delay_s); lv_obj_set_pos(s_focus_box,focus<3?12:205,focus==0?50:focus==1?76:focus==2?102:184); lv_obj_set_size(s_focus_box,focus<3?180:48,focus<3?24:32); if(mode){snprintf(b,sizeof(b),"EDIT %d",focus);lv_label_set_text(s_status,b);} }
void ui_key_event(uint32_t key)
{ int d=(key==LV_KEY_UP)?1:-1; if(key==LV_KEY_LEFT)focus=(focus+6)%7; else if(key==LV_KEY_RIGHT)focus=(focus+1)%7; else if(key==LV_KEY_ENTER){if(focus<3)mode=!mode;else if(focus==3)lv_label_set_text(s_status,"STARTED");else if(focus==4)lv_label_set_text(s_status,"MUTED");else if(focus==5)lv_label_set_text(s_status,"OPENING");else if(focus==6)lv_label_set_text(s_status,"CLOSING");} else if(mode&&key==LV_KEY_UP||mode&&key==LV_KEY_DOWN){if(focus==0)temp+=d;else if(focus==1&& (d>0||mins))mins+=d;else if(focus==2&& (d>0||delay_s>=5))delay_s+=d*5;} redraw(); }
void ui_init(void)
{ lv_obj_t *s=lv_screen_active(); lv_obj_set_style_bg_color(s,lv_color_hex(0xF5F7FA),0); txt(s,"TEMP INCUBATOR",8,4,180,25,&lv_font_montserrat_16); txt(s,"ALM: NORMAL",220,4,95,25,&lv_font_montserrat_14); lv_obj_t *c=lv_obj_create(s);lv_obj_set_pos(c,8,38);lv_obj_set_size(c,188,91);lv_obj_set_style_bg_color(c,lv_color_hex(0xDDEAF5),0);txt(c,"Current: 37.0 C",8,6,175,22,&lv_font_montserrat_16);s_target=txt(c,"Target: 37.0 C",8,30,175,22,&lv_font_montserrat_16);txt(c,"State: IDLE",8,56,175,22,&lv_font_montserrat_16);c=lv_obj_create(s);lv_obj_set_pos(c,202,38);lv_obj_set_size(c,110,91);lv_obj_set_style_bg_color(c,lv_color_hex(0xDDEAF5),0);txt(c,"RUN STATE",8,6,95,20,&lv_font_montserrat_14);s_status=txt(c,"IDLE",8,32,95,22,&lv_font_montserrat_16);txt(s,"INCUBATION",12,134,120,20,&lv_font_montserrat_14);s_time=txt(s,"Incubation: 15 min",12,155,180,22,&lv_font_montserrat_14);s_delay=txt(s,"Delay to 4C: 60 s",12,177,180,22,&lv_font_montserrat_14);txt(s,"START   MUTE   OPEN   CLOSE",205,190,110,42,&lv_font_montserrat_14);s_focus_box=lv_obj_create(s);lv_obj_set_style_bg_opa(s_focus_box,LV_OPA_TRANSP,0);lv_obj_set_style_border_width(s_focus_box,2,0);lv_obj_set_style_border_color(s_focus_box,lv_color_hex(0x2D78B8),0);lv_obj_clear_flag(s_focus_box,LV_OBJ_FLAG_CLICKABLE);redraw(); }
